import { cookies } from 'next/headers'
import { redirect } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { SidebarProvider } from '@/components/ui/sidebar'
import { AppSidebar } from '@/components/app/sidebar/AppSidebar'
import { AppHeader } from '@/components/app/sidebar/AppHeader'
import { PermissionsProvider } from '@/lib/team/permissions-context'
import { getUserPermissions } from '@/lib/team/permissions'
import { APP_NAV, type NavRole } from '@/components/app/sidebar/nav-config'
import type { PlanTier } from '@/lib/billing/feature-gate'

interface AppLayoutProps {
  children: React.ReactNode
}

export default async function AppLayout({ children }: AppLayoutProps) {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) {
    redirect('/login')
  }

  // Fetch profile, studio membership, and studio in parallel
  const [profileResult, memberResult] = await Promise.all([
    supabase
      .from('profiles')
      .select('full_name, avatar_url')
      .eq('id', user.id)
      .single(),
    supabase
      .from('studio_members')
      .select('role, studio_id, studios(id, name, slug, logo_url, plan_id)')
      .eq('user_id', user.id)
      .order('created_at', { ascending: true })
      .limit(1)
      .single(),
  ])

  const profile = profileResult.data
  const member = memberResult.data

  if (!member) {
    redirect('/onboarding')
  }

  // M11 FIX: Typed helper derived from the select shape instead of `as` cast.
  // The query selects studios(id, name, slug, logo_url) — shape is deterministic.
  type JoinedStudio = { id: string; name: string; slug: string; logo_url: string | null }
  function isJoinedStudio(v: unknown): v is JoinedStudio {
    return (
      typeof v === 'object' &&
      v !== null &&
      'name' in v &&
      typeof (v as Record<string, unknown>).name === 'string'
    )
  }

  const studio = isJoinedStudio(member.studios) ? member.studios : null

  const studioName = studio?.name ?? 'My Studio'
  const studioLogoUrl = studio?.logo_url ?? null
  const studioId = member.studio_id
  const role = member.role as NavRole

  // Subscription / plan
  let plan: PlanTier = 'solo'
  if (studioId) {
    const subResult = await supabase
      .from('subscriptions')
      .select('plan_tier')
      .eq('studio_id', studioId)
      .eq('status', 'active')
      .maybeSingle()
    if (subResult.data?.plan_tier) {
      plan = subResult.data.plan_tier as PlanTier
    }
  }

}

// Location count (for multi-location nav group)
let locationCount = 0
if (studioId) {
  const locResult = await supabase
    .from('locations')
    .select('id', { count: 'exact', head: true })
    .eq('studio_id', studioId)
  locationCount = locResult.count ?? 0
}

// Permissions — fetched once here, passed to sidebar + context provider
const permissionsSet =
  studioId && user ? await getUserPermissions(studioId, user.id) : new Set<string>()
const permissionKeys = [...permissionsSet]

// Sidebar default-open state from cookie
const cookieStore = await cookies()
const sidebarOpen = cookieStore.get('sidebar_state')?.value !== 'false'

const userName = profile?.full_name ?? user.email?.split('@')[0] ?? 'You'
const userEmail = user.email ?? ''
const userAvatarUrl = profile?.avatar_url ?? null

// Compute filtered navGroups for MobileNav (same logic as AppSidebar)
const permissions = new Set(permissionKeys)
const navGroups = APP_NAV
  .filter((group) => !(group.condition === 'multi-location' && locationCount <= 1))
  .map((group) => ({
    ...group,
    items: group.items.filter((item) => {
      if (!item.requiredRoles.includes(role)) return false
      if (item.requiredPermission && !permissions.has(item.requiredPermission)) return false
      return true
    }),
  }))
  .filter((group) => group.items.length > 0)

return (
  <PermissionsProvider permissionKeys={permissionKeys}>
    <SidebarProvider defaultOpen={sidebarOpen} className="h-svh">
      <AppSidebar
        locationCount={locationCount}
        plan={plan}
        studioName={studioName}
        studioLogoUrl={studioLogoUrl}
        role={role}
        permissionKeys={permissionKeys}
      />
      <AppHeader

